const uint32_t guest_api_table_count =
    (uint32_t)(sizeof(guest_api_table) / sizeof(guest_api_table[0]));

static int equal_ci(const char *a, const char *b) {
    while (*a && *b) {
        char x = (*a >= 'A' && *a <= 'Z') ? (char)(*a - 'A' + 'a') : *a;
        char y = (*b >= 'A' && *b <= 'Z') ? (char)(*b - 'A' + 'a') : *b;
        if (x != y) return 0;
        a++;
        b++;
    }
    return *a == *b;
}

const GuestApiEntry *guest_api_lookup(const char *dll, const char *name) {
    if (!dll || !name) return NULL;
    for (uint32_t i = 0; i < guest_api_table_count; i++) {
        const GuestApiEntry *e = &guest_api_table[i];
        if (equal_ci(e->dll, dll) && strcmp(e->name, name) == 0) return e;
    }
    return NULL;
}

int guest_api_dispatch(uint32_t index, uint32_t *out) {
    if (index >= guest_api_table_count) return A4_TRAP_STOPPED;
    const GuestApiEntry *e = &guest_api_table[index];
    if (!e->invoke) return guest_api_unimplemented(e->dll, e->name);
    return e->invoke(e->which, out);
}

int guest_api_dispatch_named(const char *dll, const char *name, uint32_t *out) {
    const GuestApiEntry *e = guest_api_lookup(dll, name);
    if (!e) return A4_TRAP_STOPPED;
    if (!e->invoke) return guest_api_unimplemented(e->dll, e->name);
    return e->invoke(e->which, out);
}

uint32_t guest_api_count_by_implementation(uint32_t implementation) {
    uint32_t n = 0;
    for (uint32_t i = 0; i < guest_api_table_count; i++)
        if (guest_api_table[i].implementation == implementation) n++;
    return n;
}

uint32_t guest_api_bound_count(void) {
    uint32_t n = 0;
    for (uint32_t i = 0; i < guest_api_table_count; i++)
        if (guest_api_table[i].invoke) n++;
    return n;
}
